/// <summary>
/// VendInvoiceInfoTable table extension
/// </summary>
[ExtensionOf(tableStr(VendInvoiceInfoTable))]
final class METVendInvoiceInfoTable_Extension
{
}

Method.Source:
    public container markupTotals()
    {
        VendInvoiceInfoLine vendInvoiceInfoLine;
        MarkupTrans         markupTrans;
        Amount              totalTaxAmount, totalAmount, amount;

        while select markupTrans
            join vendInvoiceInfoLine
                where markupTrans.TransTableId          == tableNum(VendInvoiceInfoLine) &&
                      markupTrans.TransRecId            == vendInvoiceInfoLine.RecId &&
                      vendInvoiceInfoLine.ParmId        == this.ParmId &&
                      vendInvoiceInfoLine.TableRefId    == this.TableRefId
        {
            amount = Markup::calcMarkupAmount(markupTrans, vendInvoiceInfoLine.ReceiveNow, vendInvoiceInfoLine.LineAmount, 0,
                vendInvoiceInfoLine.inclTax(), NoYes::Yes, markupTrans.CurrencyCode, markupTrans.TransDate,                     
                                     0, 0, null, false, 0, '', false, false);

            totalTaxAmount  += Tax::calcTaxAmount(markupTrans.TaxGroup, markupTrans.TaxItemGroup, markupTrans.TransDate,
                markupTrans.CurrencyCode, amount, TaxModuleType::PurchInvoice);

            totalAmount += amount;
        }

        return [totalAmount, totalTaxAmount];
    }

    public container lineAmounts()
    {
        PurchTotals     purchTotals;
        PurchCalcTax    purchCalcTax;

        purchTotals = PurchTotals::newParmTable(this, PurchUpdate::All, this.ParmId, '', this.Ordering);
        purchTotals.calc();

        return [purchTotals.purchBalance(), purchTotals.purchTaxTotal()];
    }

    public display MetGSTVariance displayMetGSTVariance()
    {
        Amount totalMarkupTax, totalMarkupAmount;
        Amount totalLineTax, totalLineAmount;

        [totalMarkupAmount, totalMarkupTax] = this.markupTotals();
        [totalLineAmount, totalLineTax]     = this.lineAmounts();

        return this.MetImportGST - (totalLineTax - totalMarkupTax);
    }

    public display MetVariance displayMetVariance()
    {
        Amount totalMarkupTax, totalMarkupAmount;
        Amount totalLineTax, totalLineAmount;

        [totalMarkupAmount, totalMarkupTax] = this.markupTotals();
        [totalLineAmount, totalLineTax]     = this.lineAmounts();

        return this.MetImportAmount - (totalLineAmount + (totalLineTax - totalMarkupTax));
    }

    public display MetVarInTol displayMETVarInTolerance()
    {
        MetVariance variance = this.displayMetVariance();

        return variance && variance <= VendParameters::find().ExtendedPriceToleranceAmount;
    }

    public display MetClaimExist displayMETHasClaimLines()
    {
        VendInvoiceInfoLine vendInvoiceInfoLine;

        select count(RecId) from vendInvoiceInfoLine
            where
                vendInvoiceInfoLine.ParmId          == this.ParmId &&
                vendInvoiceInfoLine.TableRefId      == this.TableRefId &&
                vendInvoiceInfoLine.MetClaimLine    == NoYes::Yes;

        return vendInvoiceInfoLine.RecId > 0;
    }
